mapper.select:
WITH RECURSIVE recursiveInfo AS (
 SELECT type_id, type_name, parent_id, tenant_id FROM base_product_type WHERE type_id = #{typeId}
 UNION ALL SELECT c.type_id, c.type_name, c.parent_id, c.tenant_id
 FROM base_product_type c INNER JOIN recursiveInfo ON c.parent_id = recursiveInfo.type_id
)
SELECT type_id FROM recursiveInfo
